import { useEffect, useState } from "react";
import "./App.css";

function App() {
  const [sec, setSec] = useState(0);
  const [min, setMin] = useState(0);

  useEffect(() => {
    const intervalSec = setInterval(() => {
      setSec((prevState) => {
        if (prevState === 59) {
          setMin((prevMin) => prevMin + 1);
          return 0;
        } else {
          return prevState + 1;
        }
      });
    }, 1000);
    return () => clearInterval(intervalSec);
  }, []);

  return (
    div
  );
}

export default App;
